let nextRequest = 0;

async function refresh(query, fetchData, state) {
  const requestId = ++nextRequest;
  state.query = query;
  state.loading = true;
  try {
    const result = await fetchData();
    if (requestId === nextRequest) state.result = result;
  } finally {
    state.loading = false;
  }
}

module.exports = { refresh };

