const fs = require("fs");
const vm = require("vm");
const path = require("path");

function deferred() {
  let resolve;
  const promise = new Promise((r) => { resolve = r; });
  return {promise, resolve};
}

async function observe(version, root) {
  const file = path.join(root, version, "app.js");
  const module = {exports: {}};
  vm.runInNewContext(fs.readFileSync(file, "utf8"), {
    module,
    exports: module.exports,
  });
  const state = {query: "", loading: false, result: "none"};
  const old = deferred();
  const current = deferred();
  const oldTask = module.exports.refresh("old", () => old.promise, state);
  const currentTask = module.exports.refresh("current", () => current.promise, state);
  old.resolve("old-result");
  await oldTask;
  const whileCurrentPending = {...state};
  current.resolve("current-result");
  await currentTask;
  console.log(version, {
    whileCurrentPending,
    afterCurrent: {...state},
  });
}

async function main() {
  const root = process.argv[2];
  await observe("base", root);
  await observe("target", root);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
